Note: `std.fs.cwd().readFileAlloc` may not be available in test context — guard with `@import("builtin").is_test`.

```zig
pub fn main() void {
    if (@import("builtin").is_test) return;

    var env = Environment.init(null, std.heap.page_allocator);
    defer env.deinit();
    var vm = Vm.init(std.heap.page_allocator, &env);
    defer vm.deinit();

    var args = std.process.args();
    const progName = args.next() orelse "lisp-vm";

    var file_list = std.ArrayList([]const u8).init(std.heap.page_allocator);
    defer file_list.deinit();

    var has_positional = false;

    while (args.next()) |arg| {
        if (std.mem.eql(u8, arg, "-h") or std.mem.eql(u8, arg, "--help")) {
            printHelp(progName);
            std.process.exit(0);
        }
        if (std.mem.eql(u8, arg, "-v") or std.mem.eql(u8, arg, "--version")) {
            debugPrint("lisp-vm {s}
", .{version});
            std.process.exit(0);
        }
        if (std.mem.eql(u8, arg, "-f") or std.mem.eql(u8, arg, "--file")) {
            const fname = args.next() orelse {
                debugPrint("Error: -f requires a filename
", .{});
                std.process.exit(1);
            };
            file_list.append(fname) catch unreachable;
            continue;
        }
        if (std.mem.startsWith(u8, arg, "-")) {
            debugPrint("Unknown option: {s}
", .{arg});
            debugPrint("Use --help for usage
", .{});
            std.process.exit(1);
        }
        if (has_positional) {
            debugPrint("Error: multiple positional files — use -f for each
", .{});
            std.process.exit(1);
        }
        file_list.append(arg) catch unreachable;
        has_positional = true;
    }

    // Execute files
    var i: usize = 0;
    while (i < file_list.items.len) : (i += 1) {
        // load and eval file...
    }

    // REPL
    replLoop(&vm, &env);
}
